@if($analytics['hasData']&&$c['hasPrevious'])@push('scripts')<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.2/dist/chart.umd.min.js"></script><script>(()=>{const c=@json($c);const base={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{usePointStyle:true}}},scales:{y:{beginAtZero:true,max:100,grid:{color:'#edf1f4'}},x:{grid:{display:false}}}};new Chart(document.getElementById('comparisonTrend'),{type:'line',data:{labels:c.trend.labels,datasets:[{label:String(c.currentYear),data:c.trend.current,borderColor:'#078f83',tension:.3,spanGaps:true},{label:String(c.previousYear),data:c.trend.previous,borderColor:'#9ba7b1',tension:.3,spanGaps:true}]},options:base});new Chart(document.getElementById('comparisonKpis'),{type:'bar',data:{labels:c.kpis.labels,datasets:[{label:String(c.currentYear),data:c.kpis.current,backgroundColor:'#078f83'},{label:String(c.previousYear),data:c.kpis.previous,backgroundColor:'#bac3ca'}]},options:{...base,indexAxis:'y'}});const d=document.getElementById('comparisonDepartments');if(d)new Chart(d,{type:'bar',data:{labels:c.departments.labels,datasets:[{label:String(c.currentYear),data:c.departments.current,backgroundColor:'#315b7c'},{label:String(c.previousYear),data:c.departments.previous,backgroundColor:'#c5cdd4'}]},options:{...base,indexAxis:'y'}})})();</script>@endpush @endif
